import {grade} from './questions.js';
import {practiceMenus,generators} from './scenarios.js';
const $=selector=>document.querySelector(selector);
const app=$('#app');
let exam=null,index=0,answers=[],flags=[],graded=false,fileIndex=0,hints=10,messages=[];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let dialogAction=null;
function confirmAction(title,text,action){$('#dialogTitle').textContent=title;$('#dialogText').textContent=text;dialogAction=action;$('#confirmDialog').showModal();}
$('#cancelDialog').onclick=()=>$('#confirmDialog').close();
$('#acceptDialog').onclick=()=>{$('#confirmDialog').close();dialogAction?.();};
$('#home').onclick=$('#menuButton').onclick=$('#exit').onclick=()=>{if(exam&&!graded&&answers.some(x=>x!==null))confirmAction('평가 메뉴로 이동','현재 답안이 초기화됩니다. 평가를 종료하고 메뉴로 이동할까요?',menu);else menu();};
function menu(){exam=null;$('#menuButton').textContent='평가 메뉴';$('#examTitle').textContent='AI 역량평가 연습';
 const row=(mode,title,description,count)=>`<section class="menuRow"><div><h2>${title}</h2><p>${description}<br>객관식 ${count}문제 · ${mode==='knowledge'?'개념 및 상황 판단':'업무 자료 제공'}</p></div><button class="primary" data-start="${mode}">체험 진행하기 ›</button></section>`;
 app.innerHTML=`<main class="menu"><h1>AI 역량평가 연습</h1>${row('ax','AX 직무역량평가 · B2B 컨설팅 & 영업','KT 채용공고 참고 · 기본 직무역량 5문제 + AX 문제해결 5문제',10)}<h2 class="menuGroup">AI 활용평가 · 비개발 직군 업무 상황</h2>${practiceMenus.map(([mode,title,desc,count])=>row(mode,title,desc,count)).join('')}<h2 class="menuGroup">AI 지식평가</h2>${row('knowledge','AI 기본 개념 및 실무 적용','생성형 AI · 검증 · 보안 · 프롬프트 · 업무 판단',10)}<p class="menuNote">매 평가 시작 시 자료·수치·조건과 질문 주제를 새로 조합합니다. 평가 중 문제 이동은 현재 답안을 유지합니다.<br>검토된 템플릿 기반 자체 연습이며 공식 KT·프로그래머스 시험 또는 채용 평가가 아닙니다. 어시스트는 규칙 기반 힌트입니다.</p><details class="sources"><summary>참고 자료</summary><p><a href="https://kt.recruiter.co.kr/career/jobs/125780" target="_blank" rel="noopener">KT B2B 직무 채용공고</a><a href="https://programmers.co.kr/ai-assessment?locale=ko" target="_blank" rel="noopener">프로그래머스</a><a href="https://www.testgorilla.com/ai-fluency/" target="_blank" rel="noopener">TestGorilla</a><a href="https://consumer.ftc.gov/articles/how-evaluate-online-reviews" target="_blank" rel="noopener">FTC 리뷰 검증</a><a href="https://www.nist.gov/itl/ai-risk-management-framework" target="_blank" rel="noopener">NIST AI 위험 관리</a></p></details></main>`;
 document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));}
function start(mode){exam=generators[mode]();index=0;answers=exam.questions.map(()=>null);flags=exam.questions.map(()=>false);graded=false;fileIndex=0;hints=10;messages=[];render();}
function documentHtml(d){
  if(d.type==='table')return `<div class="document"><div class="documentBanner">업무 분석 자료 · 연습용 가상 데이터</div><h2>${escape(d.name)}</h2><table><tr>${d.headers.map(h=>`<th>${escape(h)}</th>`).join('')}</tr>${d.rows.map(row=>`<tr>${row.map(v=>`<td>${escape(v)}</td>`).join('')}</tr>`).join('')}</table><p>${escape(d.note)}</p></div>`;
  if(d.type==='memo')return `<div class="document"><div class="documentBanner">정책·업무 기록 · 연습용 가상 문서</div><h2>${escape(d.name)}</h2>${d.paragraphs.map((v,i)=>`<h3>${i+1}. 기준 및 참고 사항</h3><p>${escape(v)}</p>`).join('')}</div>`;
  const row=(a,b)=>`<tr><th>${a}</th><td>${b}</td></tr>`;
  let body='';
  if(d.type==='policy')body=`<h3>1. 요금제 및 지원 기능</h3><table><tr><th>플랜</th><th>월 요금</th><th>기본 크레딧</th><th>지원 기능</th></tr>${d.policy.map(p=>`<tr>${p.map((v,i)=>`<td>${i===1?'USD '+v:i===2?v.toLocaleString():v}</td>`).join('')}</tr>`).join('')}</table><h3>2. 라이선스 운영 정책</h3><p>크레딧은 팀 내 합산됩니다. 재직자에게는 1인 1라이선스를 제공합니다. 본 연습에서는 추가 크레딧 구매와 세금은 고려하지 않습니다. 비재직자 라이선스는 명시된 회수 정책이 없으면 유지됩니다. 이번 최적화 제안에서는 비재직자 전원의 라이선스 회수를 허용합니다.</p>`;
  if(d.type==='team')body=`<h3>1. 팀 및 구독 플랜 정보</h3><table>${row('팀명',escape(d.team))}${row('플랜 코드','A2 (Advanced)')}${row('계약 라이선스',d.seats+'개')}${row('인당 월 구독료','USD 50')}${row('월 구독료 합계','USD '+d.cost)}${row('팀 월 기본 제공 크레딧',(d.seats*30000).toLocaleString()+' 크레딧')}${row('실제 사용 크레딧',d.usage.toLocaleString()+' 크레딧')}</table><h3>2. 5월 사용 중인 필수 기능</h3><p>${d.features}</p><h3>3. 운영 기준</h3><p>필수 기능을 모두 유지하고 실제 크레딧 사용량을 충족해야 합니다. 현재 라이선스는 모든 명부 인원에게 부여되어 있습니다.</p>`;
  if(d.type==='roster')body=`<h3>1. ${escape(d.team)} 인사 기준 명부</h3><table><tr><th>사번</th><th>성명</th><th>재직 상태</th></tr>${Array.from({length:d.seats},(_,i)=>`<tr><td>T-${String(i+1).padStart(3,'0')}</td><td>직원 ${i+1}</td><td>${i<d.active?'재직':i===d.active?'퇴사':i===d.active+1?'휴직':'군복무'}</td></tr>`).join('')}</table><p>명부 기준일: 2026년 5월 31일 · 재직 ${d.active}명 / 비재직 ${d.inactive}명</p>`;
  return `<div class="document"><div class="documentBanner">가상 기업 | IT 운영팀 정기 보고서</div><h2>${d.type==='policy'?'FAI 요금제 및 크레딧 정책 안내':d.type==='roster'?'전사 임직원 명부':escape(d.team)+' FAI 이용 현황 보고서'}</h2><p>보고 기준월: 2026년 5월 · 연습용 가상 자료</p>${body}</div>`;
}
function filesHtml(){return `<div class="fileLabel">파일 목록 ⌕</div><div class="files"><div class="fileTree"><small>파일명</small>${exam.documents.map((d,i)=>`<button data-file="${i}" class="${i===fileIndex?'selected':''}" title="${escape(d.name)}">${escape(d.name)}.pdf</button>`).join('')}</div><div class="fileView"><div class="fileToolbar">${escape(exam.documents[fileIndex].name)}.pdf</div>${documentHtml(exam.documents[fileIndex])}</div></div>`;}
function render(){
  const q=exam.questions[index],count=exam.questions.length,result=grade(exam.questions,answers);
  $('#menuButton').textContent=exam.mode==='ax'?'AX 직무역량평가':exam.mode==='knowledge'?'AI 지식평가':'AI 활용평가';$('#examTitle').textContent=exam.title;
  app.innerHTML=`<div class="layout"><aside class="sidebar"><button class="sideicon" id="backToMenu" aria-label="평가 메뉴">⇥</button><div aria-hidden="true">☷</div><nav class="numbers" aria-label="문제 목록">${exam.questions.map((item,i)=>`<button data-question="${i}" aria-label="${i+1}번 문제${answers[i]!==null?' 답안 선택 완료':''}${flags[i]?' 다시 풀 문제':''}" aria-current="${i===index?'step':'false'}" class="${i===index?'active':''} ${answers[i]!==null?'answered':''} ${flags[i]?'flagged':''} ${graded?(answers[i]===item.answer?'correct':'incorrect'):''}">${i+1}</button><small>${graded?(answers[i]===item.answer?'100':'0'):'-'} / 100</small>`).join('')}</nav></aside><main class="workspace"><div class="questionTop"><button data-step="-1" aria-label="이전 문제" ${index===0?'disabled':''}>‹</button><span>${index+1}. 객관식 ( ${graded?(answers[index]===q.answer?'100':'0'):'-'} / 100 )</span><button data-step="1" aria-label="다음 문제" ${index===count-1?'disabled':''}>›</button></div><div class="middle"><div class="paperScroll" id="paper">${graded?`<div class="resultLine" role="status">채점 결과: ${result.score} / 100 <small>${result.total}문제 중 ${result.correct}문제 정답 · 문제별 해설을 확인하세요.${exam.mode==='ax'?dimensionResult():''}</small></div>`:''}<section class="intro" id="intro"><div class="introTitle"><span class="pill">1 ~ ${count}</span>다음을 읽고 문제를 풀어주세요.</div><p>${escape(exam.intro)}</p>${exam.documents.length?`<p>파일 목록의 자료와 조건을 교차 확인하세요. 모든 자료는 연습용으로 생성되었습니다.</p>${filesHtml()}`:''}</section><hr class="divider"><section id="question"><div class="questionMeta"><span>${index+1}. 객관식${q.dimension?' · '+escape(q.dimension):''}</span><button class="outline ${flags[index]?'active':''}" id="flag" aria-pressed="${flags[index]}">다시 풀 문제 ⚑</button><button class="outline" id="toIntro">지문으로 이동 ↑</button>${graded?`<span class="status ${answers[index]===q.answer?'':'wrong'}">${answers[index]===q.answer?'○ 정답':answers[index]===null?'미응답':'× 오답'}</span>`:''}</div>${q.scenario?`<p class="questionText">${q.options.length===2?'다음 설명에서 적절하면 O, 그렇지 않으면 X를 선택하세요.':'다음 지문을 읽고 물음에 답하세요.'}</p><blockquote class="scenario">${escape(q.scenario)}</blockquote>`:''}<p class="questionText">${escape(q.prompt)}</p><p class="selectLabel">답안을 선택하세요 ↴</p><div class="options" role="radiogroup" aria-label="${index+1}번 답안">${q.options.map((option,i)=>`<button role="radio" aria-checked="${answers[index]===i}" data-answer="${i}" ${graded?'disabled':''} class="option ${answers[index]===i?'selected':''} ${graded&&i===q.answer?'correctAnswer':''}"><span class="circle">${i+1}</span><span>${escape(option)}</span></button>`).join('')}</div>${graded?`<div class="explanation"><strong>정답 ${q.answer+1} · ${escape(q.topic)}</strong><p>${escape(q.explanation)}</p>${answers[index]===null?'<p>이 문제는 답안을 선택하지 않았습니다.</p>':''}</div>`:''}<hr class="divider"></section></div>${exam.documents.length?assistantHtml():''}</div><div class="navigation"><span class="progress">객관식 ${count}문제 중 ${answers.filter(x=>x!==null).length}문제 제출</span><button data-step="-1" ${index===0?'disabled':''}>‹ 이전 문제</button><button data-step="1" ${index===count-1?'disabled':''}>다음 문제 ›</button></div><div class="bottom"><button id="reset">${graded?'새 문제 생성':'초기화'}</button><button class="primary" id="finish">${graded?'평가 메뉴로 이동':'채점 후 종료하기'}</button></div></main><aside class="rail"><button id="help" aria-label="이용 안내">⚑</button><button id="guide" aria-label="참고 자료">▣</button></aside></div>`;
  document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>move(Number(b.dataset.question)));
  document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>move(index+Number(b.dataset.step)));
  document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(graded)return;const scroll=$('#paper').scrollTop;answers[index]=Number(b.dataset.answer);render();$('#paper').scrollTop=scroll;});
  document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>{const scroll=$('#paper').scrollTop;fileIndex=Number(b.dataset.file);render();$('#paper').scrollTop=scroll;});
  $('#flag').onclick=()=>{const scroll=$('#paper').scrollTop;flags[index]=!flags[index];render();$('#paper').scrollTop=scroll;};
  $('#toIntro').onclick=()=>$('#intro').scrollIntoView({behavior:'smooth'});
  $('#backToMenu').onclick=()=>$('#menuButton').click();
  $('#reset').onclick=()=>confirmAction(graded?'새 문제 생성':'답안 초기화',graded?'새 지문과 수치, 보기로 평가를 다시 생성합니다. 계속할까요?':'현재 문제는 유지하고 선택 답안과 다시 풀 표시를 지웁니다. 계속할까요?',()=>{if(graded)start(exam.mode);else{answers.fill(null);flags.fill(false);render();}});
  $('#finish').onclick=()=>{if(graded){menu();return;}const missing=answers.filter(a=>a===null).length;confirmAction('채점 후 종료하기',`${missing?'미응답 '+missing+'문제는 0점으로 채점됩니다. ':''}제출 후 정답과 해설을 확인할 수 있습니다. 채점할까요?`,()=>{graded=true;render();});};
  $('#help').onclick=()=>confirmAction('이용 안내','답안을 선택하면 현재 평가 안에서 유지됩니다. 문제 번호로 이동하거나 다시 풀 문제를 표시하세요. 새 평가를 시작하거나 새로고침하면 새 문제 세트가 생성됩니다.',()=>{});
  $('#guide').onclick=()=>confirmAction('참고 자료','KT 공식 채용공고, 공개 AI 평가 소개, 로컬 기초통계 교재·소비자 조사 자료를 참고했습니다. 출처와 반영 범위는 RESEARCH.md에 있습니다. 자기소개서는 사용하지 않습니다.',()=>{});
  if($('#assistantForm')){$('#assistantForm').onsubmit=e=>{e.preventDefault();const input=$('#assistantInput').value.trim();if(!input||hints===0||graded)return;messages.push({input,reply:q.hint});hints--;const scroll=$('#paper').scrollTop;render();$('#paper').scrollTop=scroll;};$('#hintProblem').onclick=()=>{$('#assistantInput').value='현재 문제의 접근 방법을 알려주세요.';$('#assistantInput').focus();};$('#hintFiles').onclick=()=>{$('#assistantInput').value='어떤 자료를 확인해야 하나요?';$('#assistantInput').focus();};}
}
function dimensionResult(){return ['기본 직무역량','AX 문제해결'].map(d=>{const indices=exam.questions.map((q,i)=>q.dimension===d?i:-1).filter(i=>i>=0);const correct=indices.filter(i=>answers[i]===exam.questions[i].answer).length;return `<br>${d}: ${correct}/${indices.length} 정답 (${Math.round(correct/indices.length*100)}점)`;}).join('');}
function assistantHtml(){return `<aside class="assistant"><div class="assistantHead">AI 어시스트 <small>${hints}회 남음</small></div><p>현재 문제의 자료와 판단 기준을 확인하세요.<br>연습용 · 현재 문제의 정해진 힌트 제공</p><div class="assistantBody" aria-live="polite">${messages.map(m=>`<div class="message">${escape(m.input)}</div><div class="message">${escape(m.reply)}</div>`).join('')}</div><div class="assistantTools"><button class="outline" id="hintProblem">문제 ⌃</button><button class="outline" id="hintFiles">첨부 파일 ⌃</button></div><form id="assistantForm"><input id="assistantInput" aria-label="힌트 질문" placeholder="무엇을 도와드릴까요?" maxlength="300" ${hints===0||graded?'disabled':''}><button aria-label="힌트 요청" ${hints===0||graded?'disabled':''}>↑</button></form></aside>`;}
function move(next){if(next<0||next>=exam.questions.length)return;index=next;render();if(exam.documents.length)$('#question').scrollIntoView();}
menu();
